addCommandHandler("task", function()
    outputDebugString(getPedSimplestTask(localPlayer) or "no task")
end)

addCommandHandler("suicide", function(player)
    killPed(player)
end)

addEventHandler("onPlayerSpawn", root, function()
    setPedArmor(source, 100)
end)

addEventHandler("onClientPlayerWasted", localPlayer, function()
    setPedBleeding(localPlayer, true)
end)

addCommandHandler("getout", function()
    setPedExitVehicle(localPlayer)
end)

addCommandHandler("jetpack", function(player)
    setPedWearingJetpack(player, not isPedWearingJetpack(player))
end)

addCommandHandler("heal", function(player)
    usePickup(medkit, player)
end)

bindKey("b", "both", function(key, state)
    setVoiceTransmitting(state == "down")
end)

local speaking = {}

addEventHandler("onClientPlayerVoiceStart", root, function()
    speaking[source] = true
end)

addEventHandler("onClientPlayerVoiceStop", root, function()
    if not isPlayerTalking(source) then
        speaking[source] = nil
    end
end)

addCommandHandler("players", function()
    outputDebugString(getPlayerCount() .. " players online")
end)
